<?php
declare(strict_types=1);

final class SourceHistory
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function safe(mixed $value):int
    {
        $value=(string)$value;if(!preg_match('/^[0-9]+$/D',$value))throw new HttpError(409,'Số lượng hoặc giá vốn lịch sử nguồn không hợp lệ.');$value=ltrim($value,'0') ?: '0';if(strlen($value)>16||strlen($value)===16&&strcmp($value,'9007199254740991')>0)throw new HttpError(409,'Tổng lịch sử nguồn vượt phạm vi xử lý.');return (int)$value;
    }
    public function get(string $id,array $input,bool $all=false):array
    {
        if(!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id)||array_diff(array_keys($input),['page']))throw new HttpError(400,'Nguồn hoặc trang lịch sử không hợp lệ.');$page=$input['page'] ?? '1';if(!is_string($page)||!preg_match('/^[1-9][0-9]{0,5}$/D',$page)||(int)$page>100000)throw new HttpError(400,'Trang lịch sử không hợp lệ.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $lot=$this->query('SELECT id,unlimited,archived,customer_type,data FROM jingo_supply_lots WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if(!$lot)throw new HttpError(404,'Không tìm thấy nguồn.');$data=json_decode($lot['data'],true,512,JSON_THROW_ON_ERROR);$unlimited=(bool)$lot['unlimited'];
            if($unlimited){$summary=$this->query('SELECT COUNT(*) AS total,COALESCE(SUM(quantity),0) AS quantity,COALESCE(SUM(CAST(quantity AS DECIMAL(50,0))*unit_cost),0) AS amount FROM jingo_supply_purchases WHERE lot_id=?',[$id])->fetch(PDO::FETCH_ASSOC);}
            else{$summary=$this->query('SELECT COUNT(*) AS total,COALESCE(SUM(quantity),0) AS quantity,COALESCE(SUM(CAST(quantity AS DECIMAL(50,0))*unit_cost),0) AS amount,COALESCE(SUM(IF(released=0,quantity,0)),0) AS active_quantity,COALESCE(SUM(IF(released=1,quantity,0)),0) AS released_quantity,COALESCE(SUM(IF(released=0,CAST(quantity AS DECIMAL(50,0))*unit_cost,0)),0) AS active_amount FROM jingo_supply_allocations WHERE lot_id=?',[$id])->fetch(PDO::FETCH_ASSOC);}
            $total=self::safe($summary['total']);if($all&&$total>10000)throw new HttpError(400,$unlimited?'Nguồn vượt 10.000 dòng. Dùng sao kê nhà cung cấp theo kỳ ngắn hơn; dữ liệu không bị cắt.':'Lô vượt 10.000 đơn phân bổ. Có thể xem từng trang; xuất phân bổ theo kỳ chưa được hỗ trợ.');$page=min((int)$page,max(1,(int)ceil($total/25)));$limit=$all?10000:25;$offset=$all?0:($page-1)*25;
            $sql=$unlimited?'SELECT p.id,p.order_id,p.quantity,p.unit_cost,p.data,p.created_at,o.code,o.booking_status,a.order_id AS archived_order FROM jingo_supply_purchases p JOIN jingo_orders o ON o.id=p.order_id LEFT JOIN jingo_order_archives a ON a.order_id=o.id WHERE p.lot_id=? ORDER BY p.created_at DESC,p.id DESC':'SELECT o.id,a.order_id,a.quantity,a.unit_cost,a.released,o.created_at,o.code,o.booking_status,r.order_id AS archived_order FROM jingo_supply_allocations a JOIN jingo_orders o ON o.id=a.order_id LEFT JOIN jingo_order_archives r ON r.order_id=o.id WHERE a.lot_id=? ORDER BY o.created_at DESC,o.id DESC';$rows=[];
            foreach($this->query($sql." LIMIT $limit OFFSET $offset",[$id])->fetchAll(PDO::FETCH_ASSOC) as $record){$quantity=self::safe($record['quantity']);$unitCost=self::safe($record['unit_cost']);if($quantity>0&&$unitCost>intdiv(Pricing::MAX_SAFE,$quantity))throw new HttpError(409,'Giá trị dòng lịch sử vượt phạm vi xử lý.');$purchase=$unlimited?json_decode($record['data'],true,512,JSON_THROW_ON_ERROR):[];$row=['id'=>$record['id'],'orderId'=>$record['order_id'],'orderCode'=>$purchase['orderCode'] ?? $record['code'],'createdAt'=>str_replace(' ','T',$record['created_at']).'Z','quantity'=>$quantity,'unitCost'=>$unitCost,'amount'=>$quantity*$unitCost,'bookingStatus'=>$record['booking_status'],'orderArchived'=>$record['archived_order']!==null];if(!$unlimited)$row['released']=(bool)$record['released'];$rows[]=$row;}
            $report=['source'=>['id'=>$lot['id'],'unlimited'=>$unlimited,'archived'=>(bool)$lot['archived'],'supplierName'=>$data['supplierName'] ?? '','productName'=>$data['productName'] ?? '','variantName'=>$data['variantName'] ?? '','customerType'=>$lot['customer_type']],'mode'=>$unlimited?'PURCHASES':'ALLOCATIONS','timeBasis'=>$unlimited?'PURCHASE_CREATED':'ORDER_CREATED','total'=>$total,'quantity'=>self::safe($summary['quantity']),'amount'=>self::safe($summary['amount']),'page'=>$page,'pageSize'=>25,'rows'=>$rows];if(!$unlimited)$report+=['activeQuantity'=>self::safe($summary['active_quantity']),'releasedQuantity'=>self::safe($summary['released_quantity']),'activeAmount'=>self::safe($summary['active_amount'])];$this->db->commit();return $report;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public static function csv(array $report):string
    {
        $source=$report['source'];$groups=['ADULT'=>'Người lớn','CHILD'=>'Trẻ em','SENIOR'=>'Người cao tuổi','LOCAL_ADULT'=>'Người lớn · Địa phương','LOCAL_CHILD'=>'Trẻ em · Địa phương','LOCAL_SENIOR'=>'Người cao tuổi · Địa phương'];$header=['Mã nguồn','Nhà cung cấp','Sản phẩm','Gói vé','Nhóm khách',$source['unlimited']?'Mã ghi nhận lấy vé':'Mã đơn nội bộ',$source['unlimited']?'Ngày lấy (GMT+7)':'Ngày tạo đơn (GMT+7)','Mã đơn','Số lượng','Giá mua (VND)','Thành tiền (VND)','Trạng thái đơn hiện tại','Đơn lưu trữ'];if(!$source['unlimited'])$header[]='Trạng thái phân bổ hiện tại';$lines=[$header];$zone=new DateTimeZone('Asia/Ho_Chi_Minh');foreach($report['rows'] as $row){$line=[$source['id'],$source['supplierName'],$source['productName'],$source['variantName'],$groups[$source['customerType']] ?? $source['customerType'],$row['id'],(new DateTimeImmutable($row['createdAt']))->setTimezone($zone)->format('Y-m-d H:i:s'),$row['orderCode'],$row['quantity'],$row['unitCost'],$row['amount'],$row['bookingStatus'],$row['orderArchived']?'Có':'Không'];if(!$source['unlimited'])$line[]=$row['released']?'Đã trả nguồn':'Đang phân bổ';$lines[]=$line;}return "\xEF\xBB\xBF".implode("\r\n",array_map(fn($line)=>implode(',',array_map([SupplierStatements::class,'csvCell'],$line)),$lines))."\r\n";
    }
}
